// ---------- Top navigation: one config (S.nav) renders desktop dropdowns and mobile expandable groups ----------
// Labels are real links to their overview pages; a separate toggle button opens each menu (nav.js).
const APP = 'https://app.iparkar.com';
const chevron = '<svg class="nav-toggle__icon" viewBox="0 0 16 16" width="16" height="16" aria-hidden="true" focusable="false"><path d="M4 6l4 4 4-4" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>';
const navStatus = st => st ? ` <span class="nav-status${/soon/i.test(st)?' nav-status--soon':''}">${esc(st)}</span>` : '';
const navLinkAttrs = (href, here) => href===here ? ' aria-current="page"' : '';
function navHtml(here, section) {
  const item = (m, here) => `<li><a class="nav-menu__link" href="${m.href}"${navLinkAttrs(m.href,here)}>${esc(m.label)}${navStatus(m.status)}</a>${m.children?`<ul class="nav-menu__sub">${m.children.map(c=>`<li><a class="nav-menu__link nav-menu__link--sub" href="${c.href}"${navLinkAttrs(c.href,here)}>${esc(c.label)}${navStatus(c.status)}</a></li>`).join('')}</ul>`:''}</li>`;
  const top = t => {
    const exact = t.href===here, inSection = !exact && section===t.id;
    const cur = exact ? ' aria-current="page"' : inSection ? ' aria-current="true"' : '';
    if (!t.menu) return `<li class="nav-item"><a class="ip-nav-link" href="${t.href}"${cur}>${esc(t.label)}</a></li>`;
    const mid = `nav-menu-${t.id}`;
    return `<li class="nav-item nav-group" data-nav-group><div class="nav-group__row"><a class="ip-nav-link nav-group__label" href="${t.href}"${cur}>${esc(t.label)}</a><button type="button" class="nav-toggle" aria-expanded="false" aria-controls="${mid}" aria-label="${esc(t.label)} menu" data-nav-toggle>${chevron}</button></div><div class="nav-menu" id="${mid}"><ul class="nav-menu__list">${t.menu.map(m=>item(m,here)).join('')}</ul><a class="nav-menu__all" href="${t.href}">${t.id==='resources'?'All resources':'All practice exams'} <span aria-hidden="true">→</span></a></div></li>`;
  };
  return `<header class="site-nav" data-site-nav><div class="site-nav__inner"><a class="brand" href="/" aria-label="iParkar Learning home"><img src="/assets/iparkar-mark-primary.svg" alt="" width="36" height="36"><span class="brand__name">iParkar <span>Learning</span></span></a><nav class="site-menu" id="site-menu" aria-label="Main"><ul class="nav-links">${S.nav.map(top).join('')}</ul></nav><div class="nav-actions"><a class="nav-signin-link" href="${APP}/login" data-auth-link>Sign in</a><button type="button" class="nav-burger" aria-expanded="false" aria-controls="site-menu" data-nav-burger><span class="nav-burger__bars" aria-hidden="true"></span><span class="nav-burger__text">Menu</span></button></div></div></header>`;
}
// Which top-level item a page belongs to (for aria-current="true" on the section label).
const navSection = id => {
  for (const t of S.nav) { if (t.id===id) return t.id; for (const m of t.menu||[]) { if (m.id===id || (m.children||[]).some(c=>c.id===id)) return t.id; } }
  return null;
};
