// Pages that show local prices (regional-prices.js fills every [data-local-price]).
const pricedPages = ['resources','studyCourses','aspCourse','cspCourse','pmpCourse','pxASP','pxCSP','pxCIH','pxEPI','pxQEP','pxCIT','pxPMP'];
function normalize(html) {
  for (const [id,url] of Object.entries(routes)) html = html.replaceAll(`href="#${id}"`, `href="${url}"`);
  return html.replace(/(src|href)="(assets\/|styles\.css|favicon\.svg|apple-touch-icon\.png|site\.webmanifest)/g,'$1="/$2');
}
for (const [id,title,description,raw] of pages) {
  let body=raw;
  if (!body.includes('<h1')) body=body.replace('<h2','<h1').replace('</h2>','</h1>');
  const url=`https://iparkar.com${routes[id]}`;
  // Section for the header, and breadcrumb ancestors, for every page.
  const parents = {books:['resources'],studyCourses:['resources'],aspCourse:['resources','studyCourses'],cspCourse:['resources','studyCourses'],pmpCourse:['resources','studyCourses'],sat:['resources'],learning:['resources'],
    ...Object.fromEntries(['pxASP','pxCSP','pxCIH','pxEPI','pxQEP','pxCIT','pxPMP'].map(k=>[k,['practice']])),
    ...Object.fromEntries(['nebosh','iosh','bohs','level3','level6','memberships'].map(k=>[k,['courses']])),
    ...Object.fromEntries(Object.keys(summaryData).map(k=>[k,['certifications','selection',summaryData[k].group]])),
    selection:['certifications'], ...Object.fromEntries(groups.map(g=>[g.id,['certifications','selection']]))};
  const current=(parents[id]||[id])[0];
  const navLabel = key => { for (const t of S.nav) { if (t.id===key) return t.label; for (const m of t.menu||[]) { if (m.id===key) return m.label; const c=(m.children||[]).find(c=>c.id===key); if (c) return c.label; } } return null; };
  const crumbName = key => key==='selection'?'Select certification':key==='certifications'?'Certification pathways':key==='courses'?'Certificate courses':key==='sat'?'SAT':key.startsWith('px')?navLabel(key)+' practice exam':groups.find(g=>g.id===key)?.title || navLabel(key) || (key==='contact'?'Contact us':key==='bohs'?'BOHS courses':key==='level3'?'Level 3 certificates':key==='level6'?'Level 6 diplomas':key==='memberships'?'Membership pathways':key==='certoh'?'ICertOH':['nebosh','iosh'].includes(key)?key.toUpperCase()+' courses':key.toUpperCase());
  const label = crumbName(id);
  const crumbs = [{id:'home',label:'Home'},...(parents[id]||[]).map(key=>({id:key,label:crumbName(key)})),{id,label}];
  const schema=[{'@context':'https://schema.org','@type':'WebSite',name:'iParkar Learning',url:'https://iparkar.com/'}, {'@context':'https://schema.org','@type':'Organization',name:'iParkar Learning',url:'https://iparkar.com/',logo:'https://iparkar.com/assets/icon-512.png',sameAs:(S.footer.social||[]).map(s=>s.href)}, {'@context':'https://schema.org','@type':'WebPage',name:title,url,description}];
  if(id!=='home') schema.push({'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:crumbs.map((c,i)=>({'@type':'ListItem',position:i+1,name:c.label,item:'https://iparkar.com'+routes[c.id]}))});
  let html=normalize(`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)} | iParkar Learning</title><meta name="description" content="${esc(description)}"><meta name="theme-color" content="#02093a"><link rel="canonical" href="${url}"><meta property="og:type" content="website"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:url" content="${url}"><meta property="og:site_name" content="iParkar Learning"><meta name="twitter:card" content="summary"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="apple-touch-icon" href="/apple-touch-icon.png"><link rel="manifest" href="/site.webmanifest"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link rel="stylesheet" href="/styles.css"><script type="application/ld+json">${JSON.stringify(schema).replaceAll('<','\\u003c')}</script></head><body><a class="skip-link" href="#main">Skip to content</a>${navHtml(routes[id], navSection(id) || current)}<main id="main" tabindex="-1"><div class="container tab-panel">${id!=='home'?`<nav class="breadcrumbs" aria-label="Breadcrumb">${crumbs.map((c,i)=>i===crumbs.length-1?`<span aria-current="page">${esc(c.label)}</span>`:`<a href="${routes[c.id]}">${esc(c.label)}</a>`).join(' / ')}</nav>`:''}${body}</div></main><footer class="site-footer"><div class="container site-footer__inner"><span>${esc(S.footer.copyright)}</span><nav aria-label="Footer"><a href="/about/">About</a><a href="/resources/">Resources</a>${S.footer.links.map(l=>`<a href="/${l.href}">${esc(l.label)}</a>`).join('')}<a href="/contact/">Contact</a></nav>${socialLinks()}</div></footer><script src="/nav.js" defer></script><script src="/legacy-routes.js" defer></script>${pricedPages.includes(id)?'<script src="/regional-prices.js" defer></script>':''}${id==='practice'?'<script src="/regional-prices.js" defer></script><script src="/site-config.js" defer></script><script src="/questions-free.js" defer></script><script src="/free-exam.js" defer></script><script src="/app.js" defer></script>':''}</body></html>`);
  if (id === 'practice' || pricedPages.includes(id)) for (const [file, asset] of Object.entries(pricingAssets)) html = html.replaceAll(`"/${file}"`, `"${asset}"`);
  const file=routes[id]==='/'?'index.html':routes[id].slice(1)+'index.html';
  fs.mkdirSync(file.includes('/')?file.slice(0,file.lastIndexOf('/')):'.',{recursive:true}); fs.writeFileSync(file,html+'\n');
}

// Hand-written pages (legal pages, 404) get the same generated header and nav.js on every build.
for (const [file, here] of [['terms.html','/terms'],['privacy.html','/privacy'],['refunds.html','/refunds'],['404.html','']]) {
  let h = fs.readFileSync(file, 'utf8');
  const head = navHtml(here, null);
  if (/<header class="site-nav"[\s\S]*?<\/header>/.test(h)) h = h.replace(/<header class="site-nav"[\s\S]*?<\/header>/, () => head);
  else h = h.replace(/<body([^>]*)>/, (m) => m + head);
  if (!h.includes('src="/nav.js"')) h = h.replace('</body>', '<script src="/nav.js" defer></script></body>');
  fs.writeFileSync(file, h);
}
fs.writeFileSync('sitemap.xml',`<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${pages.map(([id])=>`<url><loc>https://iparkar.com${routes[id]}</loc></url>`).join('')}${['terms','privacy','refunds'].map(p=>`<url><loc>https://iparkar.com/${p}</loc></url>`).join('')}</urlset>\n`);
fs.writeFileSync('robots.txt','User-agent: *\nAllow: /\n\nSitemap: https://iparkar.com/sitemap.xml\n');
console.log(`Generated ${pages.length} static pages and sitemap.`);
